        urduTranslation: `۱. اے ہمارے رب! ہم سے قبول فرما، بے شک تو ہی سننے والا جاننے والا ہے۔ [کنز الایمان]
۲. اے ہمارے رب! ہمیں اپنا فرمانبردار بنا اور ہماری اولاد میں سے ایک ایسی امت اٹھا جو تیری فرمانبردار ہو، اور ہمیں ہماری عبادت کے طریقے دکھا اور ہم پر توبہ کی نظر فرما، بے شک تو ہی بڑا توبہ قبول فرمانے والا مہربان ہے۔
۳. اے ہمارے رب! ہم نے اپنی جانوں پر زیادتی کی اور اگر تو نے ہمیں نہ بخشا اور ہم پر رحم نہ فرمایا تو ہم ضرور نقصان پانے والوں میں سے ہو جائیں گے۔ (دعاۓ حضرت آدمؑ)
۴. اے ہمارے رب! پس ہمارے گناہ بخش دے، ہماری برائیاں ہم سے دور فرما دے اور ہمیں نیک لوگوں کے ساتھ وفات عطا فرما۔
۵. اے ہمارے رب! اگر ہم بھولیں یا چوکیں تو ہماری پکڑ نہ فرما۔ اے ہمارے رب! اور ہم پر بھاری بوجھ نہ رکھ جیسا تو نے ہم سے اگلوں پر رکھا تھا۔ اے ہمارے رب! اور ہم پر وہ بوجھ نہ ڈال جس کی ہمیں سہار نہ ہو۔ اور ہمیں معاف فرما دے، ہمیں بخش دے، اور ہم پر رحم فرما، تو ہمارا مولیٰ ہے پس کافروں پر ہماری مدد فرما۔`,
