        chapterTitleUrdu: 'دسواں باب: بارگاہِ الٰہی میں مناجات، شفاعت کی التجا اور اختتامی دعا',
        chapterTitleEnglish: 'Chapter 10: Supplication, Intercession & Divine Grace',
        arabicMatn: `يَا أَكْرَمَ الْخَلْقِ مَا لِي مَنْ أَلُوذُ بِهِ ... سِوَاكَ عِنْدَ حُلُولِ الْحَادِثِ الْعَمَمِ
وَلَنْ يَضِيقَ رَسُولَ اللَّهِ جَاهُكَ بِي ... إِذَا الْكَرِيمُ تَجَلَّى بِاسْمِ مُنْتَقِمِ
فَإِنَّ مِنْ جُودِكَ الدُّنْيَا وَضَرَّتَهَا ... وَمِنْ عُلُومِكَ عِلْمَ اللَّوْحِ وَالْقَلَمِ
يَا رَبِّ بِالْمُصْطَفَى بَلِّغْ مَقَاصِدَنَا ... وَاغْفِرْ لَنَا مَا مَضَى يَا وَاسِعَ الْكَرَمِ
وَاغْفِرْ إِلَهِي لِكُلِّ الْمُسْلِمِينَ بِمَا ... يَتْلُونَ فِي الْمَسْجِدِ الأَقْصَى وَفِي الْحَرَمِ`,
        urduTranslation: `اے تمام مخلوق میں سب سے زیادہ معزز و مکرم! مصیبتِ عام کے وقت آپ کے سوا میرا کوئی ایسا ملجا و ماویٰ نہیں جس کی پناہ پکڑوں۔
یا رسول اللہ! آپ کی بارگاہ و شفاعت مجھ عاصی کے لیے تنگ نہ ہوگی، جب ربِ کریم اپنے اسمِ منتقم کے ساتھ جلال فرمائے گا۔
کیونکہ دنیا اور آخرت آپ ہی کے جود و سخا کا حصہ ہیں، اور لوح و قلم کا علم آپ کے علوم کا ایک گوشہ ہے!
اے ہمارے رب! مصطفیٰ کریم ﷺ کے وسیلے سے ہمارے تمام پاک مقاصد پورے فرما، اور ہمارے تمام پچھلے گناہ بخش دے اے وسیع کرم والے!
اور اے میرے پروردگار! تمام مسلمانوں کو بخش دے ان آیات کے صدقے جو مسجد اقصیٰ اور حرمِ مکہ میں تلاوت کی جاتی ہیں!`,
        englishSynopsis: 'Concluding supplication beseeching Allah through the exalted status of the Beloved Messenger ﷺ for forgiveness and fulfillment of all righteous hopes.',
        scholarlyNotes: 'The couplet "Ya Rabbi bil-Mustafa balligh maqasidana" is traditionally recited after gatherings to invoke divine mercy.',
