  // 7. MATN ABI SHUJA' (Shafi'i Fiqh — غاية الاختصار)
  // =========================================================================
  'CANON-FIQ-SHAF-001': {
    workId: 'CANON-FIQ-SHAF-001',
    verifiedExternalUrl: 'https://archive.org',
    verifiedExternalName: 'Classical Shafi\'i Heritage (Matn Abi Shuja\')',
    chapters: [
      {
        chapterId: 'shaf_1',
        chapterTitleArabic: 'كِتَابُ الطَّهَارَةِ (فُرُوضُ الْوُضُوءِ وَسُنَنُهُ)',
        chapterTitleUrdu: 'کتاب الطہارت: فقہ شافعی میں وضو کے ۶ فرائض اور سنتیں',
        chapterTitleEnglish: 'Purification: The Six Obligations (Fara\'id) of Wudu in Shafi\'i Fiqh',
        arabicMatn: `قَالَ الْقَاضِي أَبُو شُجَاعٍ أَحْمَدُ بْنُ الْحُسَيْنِ الأَصْفَهَانِيُّ رَحِمَهُ اللَّهُ:

«فُرُوضُ الْوُضُوءِ سِتَّةُ أَشْيَاءَ:
١. النِّيَّةُ عِنْدَ غَسْلِ الْوَجْهِ.
٢. وَغَسْلُ الْوَجْهِ.
٣. وَغَسْلُ الْيَدَيْنِ إِلَى الْمِرْفَقَيْنِ.
٤. وَمَسْحُ بَعْضِ الرَّأْسِ.
٥. وَغَسْلُ الرِّجْلَيْنِ إِلَى الْكَعْبَيْنِ.
٦. وَالتَّرْتِيبُ عَلَى مَا ذَكَرْنَاهُ.

وَسُنَنُهُ عَشَرَةُ أَشْيَاءَ: التَّسْمِيَةُ، وَغَسْلُ الْكَفَّيْنِ قَبْلَ إِدْخَالِهِمَا الإِنَاءَ، وَالسِّوَاكُ، وَالْمَضْمَضَةُ، وَالاسْتِنْشَاقُ، وَمَسْحُ جَمِيعِ الرَّأْسِ، وَمَسْحُ الأُذُنَيْنِ، وَتَخْلِيلُ اللِّحْيَةِ الْكَثَّةِ، وَتَخْلِيلُ أَصَابِعِ الْيَدَيْنِ وَالرِّجْلَيْنِ، وَتَقْدِيمُ الْيُمْنَى عَلَى الْيُسْرَى، وَالتَّثْلِيثُ، وَالْمُوَالاةُ».`,
        urduTranslation: `قاضی ابو شجاع اصفہانی رحمہ اللہ فرماتے ہیں: "فقہ شافعی میں وضو کے ۶ فرائض ہیں:
۱. چہرہ دھوتے وقت نیت کرنا۔
۲. پورے چہرے کا دھونا۔
۳. کہنیوں سمیت دونوں ہاتھوں کا دھونا۔
۴. سر کے کچھ حصے کا مسح کرنا۔
۵. ٹخنوں سمیت دونوں پاؤں کا دھونا۔
۶. ان ارکان کو اسی ترتیب کے ساتھ ادا کرنا۔

اور وضو کی اہم سنتیں ہیں: بسم اللہ پڑھنا، دونوں ہتھیلیوں کا دھونا، مسواک کرنا، کلی کرنا، ناک میں پانی ڈالنا، پورے سر کا مسح کرنا، کانوں کا مسح کرنا، داڑھی اور انگلیوں کا خلال کرنا، دائیں عضو کو بائیں پر مقدم رکھنا، ہر عضو کو تین تین بار دھونا، اور پے در پے دھونا"۔`,
        englishSynopsis: 'Concise codification of the six obligatory pillars (including intention and order) and ten Sunnahs of ablution according to the Shafi\'i school.',
        scholarlyNotes: 'Unlike the Hanafi school where Niyyah and Tartib are Sunnah, in the Shafi\'i school they are obligatory pillars (Fard).',
      },
    ],
  },

