  // 8. MATN IBN ASHIR (Maliki Fiqh — المرشد المعين)
  // =========================================================================
  'CANON-FIQ-MAL-001': {
    workId: 'CANON-FIQ-MAL-001',
    verifiedExternalUrl: 'https://archive.org',
    verifiedExternalName: 'Classical Maliki Heritage (Matn Ibn Ashir)',
    chapters: [
      {
        chapterId: 'mal_1',
        chapterTitleArabic: 'فَرَائِضُ الْوُضُوءِ وَسُنَنُهُ فِي فِقْهِ الإِمَامِ مَالِكٍ',
        chapterTitleUrdu: 'منظوم فقہِ مالکی: وضو کے ۷ فرائض (فرائضِ وضو بسندِ امام مالک)',
        chapterTitleEnglish: 'Purification: The Seven Obligations of Wudu in Maliki Fiqh',
        arabicMatn: `قَالَ الإِمَامُ عَبْدُ الْوَاحِدِ ابْنُ عَاشِرٍ رَحِمَهُ اللَّهُ:

«فَرَائِضُ الْوُضُوءِ سَبْعَةٌ وَهِيَ:
غَسْلُكَ وَجْهًا، ثُمَّ غَسْلُ الْيَدَيْنِ ... لِلْمِرْفَقَيْنِ، وَامْسَحَنْ كُلَّ الرَّأْسِ
وَغَسْلُ رِجْلَيْكَ مَعَ الْكَعْبَيْنِ ... وَالدَّلْكُ، وَالْفَوْرُ بِذَاكَ، فَاعْنِ
وَالنِّيَّةُ اشْرُطْ فِي ابْتِدَائِهِ تُثَبْ ... نِيَّةَ فَرْضٍ أَوْ لِمَا لَهُ انْتُدِبْ

وَسُنَنُهُ: غَسْلُ الْيَدَيْنِ لِلْكُوعَيْنِ، وَالْمَضْمَضَةُ، وَالاسْتِنْشَاقُ، وَالاسْتِنْثَارُ، وَرَدُّ مَسْحِ الرَّأْسِ، وَمَسْحُ الأُذُنَيْنِ، وَالتَّرْتِيبُ».`,
        urduTranslation: `علامہ ابن عاشر رحمہ اللہ مالکی فقہ کے احکام منظوم انداز میں فرماتے ہیں: "وضو کے سات فرائض ہیں:
۱. چہرے کا دھونا، ۲. کہنیوں تک دونوں ہاتھوں کا دھونا، ۳. پورے سر کا مسح کرنا، ۴. ٹخنوں سمیت دونوں پاؤں کا دھونا، ۵. دَلک (اعضاء کو ملنا)، ۶. فور (پے در پے بغیر تاخیر دھونا)، ۷. اور ابتدا میں نیت کی شرط لگانا۔
اور وضو کی سنتیں ہیں: گٹوں تک ہاتھ دھونا، کلی کرنا، ناک میں پانی چڑھانا اور جھاڑنا، سر کے مسح کو پیچھے سے آگے لوٹانا، کانوں کا مسح اور ترتیب"۔`,
        englishSynopsis: 'The classical rhymed Maliki text detailing the seven obligations of ablution, notably including rubbing the limbs (Dalk) and continuity (Fawr).',
        scholarlyNotes: 'Dalk (gentle rubbing while washing) is a distinct requirement in the Maliki Madhhab, following the authentic practice of the People of Madinah.',
      },
    ],
  },

