  // =========================================================================
  'CANON-HAD-002': {
    workId: 'CANON-HAD-002',
    verifiedExternalUrl: 'https://sunnah.com/muslim',
    verifiedExternalName: 'Sunnah.com (Complete Sahih Muslim)',
    chapters: [
      {
        chapterId: 'mus_1',
        chapterTitleArabic: 'كِتَابُ الإِيمَانِ (حَدِيثُ جِبْرِيلَ)',
        chapterTitleUrdu: 'کتاب الایمان (حدیثِ جبریل: اسلام، ایمان اور احسان)',
        chapterTitleEnglish: 'Book 1: Faith & The Comprehensive Hadith of Jibril',
        arabicMatn: `عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ﷺ... قَالَ: يَا مُحَمَّدُ، أَخْبِرْنِي عَنِ الإِسْلامِ؟ فَقَالَ رَسُولُ اللَّهِ ﷺ: «الإِسْلامُ أَنْ تَشْهَدَ أَنْ لا إِلَهَ إِلا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَتُقِيمَ الصَّلاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلا». قَالَ: فَأَخْبِرْنِي عَنِ الإِحْسَانِ؟ قَالَ: «أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ».`,
        urduTranslation: `حضرت عمر بن الخطاب رضی اللہ عنہ نے فرمایا کہ جبریل علیہ السلام نے رسول اللہ ﷺ سے اسلام اور احسان کے بارے میں پوچھا، تو آپ ﷺ نے فرمایا: "اسلام یہ ہے کہ تم گواہی دو کہ اللہ کے سوا کوئی معبود نہیں اور محمد (ﷺ) اللہ کے رسول ہیں، نماز قائم کرو، زکوٰۃ دو، رمضان کے روزے رکھو اور استطاعت ہو تو حج کرو"... اور احسان یہ ہے کہ "تم اللہ کی عبادت اس طرح کرو گویا تم اسے دیکھ رہے ہو، اور اگر تم اسے نہ دیکھ سکو تو وہ تمہیں دیکھ رہا ہے"۔`,
        englishSynopsis: 'The master tradition outlining the three dimensions of Islam: Outward Shariah (Islam), Inward Aqeedah (Iman), and Spiritual Vigilance (Ihsan).',
        scholarlyNotes: 'Referred to by scholars as Umm al-Sunnah (The Mother of Traditions) due to its comprehensive synthesis of religion.',
      },
      {
        chapterId: 'mus_2',
        chapterTitleArabic: 'كِتَابُ الطَّهَارَةِ (شَطْرُ الإِيمَانِ)',
        chapterTitleUrdu: 'کتاب الطہارت (پاکیزگی نصف ایمان ہے)',
        chapterTitleEnglish: 'Book 2: Purification (Half of Faith)',
        arabicMatn: `عَنْ أَبِي مَالِكٍ الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ:

«الطُّهُورُ شَطْرُ الإِيمَانِ، وَالْحَمْدُ لِلَّهِ تَمْلأُ الْمِيزَانَ، وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلآنِ - أَوْ تَمْلأُ - مَا بَيْنَ السَّمَاوَاتِ وَالأَرْضِ، وَالصَّلاةُ نُورٌ، وَالصَّدَقَةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ».`,
        urduTranslation: `حضرت ابو مالک اشعری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ ﷺ نے فرمایا: "طہارت و پاکیزگی نصف ایمان ہے، اور 'الحمد للہ' ترازو کو بھر دیتا ہے، اور 'سبحان اللہ' اور 'الحمد للہ' آسمانوں اور زمین کے درمیانی خلا کو بھر دیتے ہیں، اور نماز نور ہے، صدقہ دلیل ہے، صبر روشنی ہے، اور قرآن تمہارے حق میں یا تمہارے خلاف دلیل ہے"۔`,
        englishSynopsis: 'Ritual purification cleanses the soul, prayer generates divine illumination, and patience provides enduring radiance in adversity.',
        scholarlyNotes: 'Purity encompasses both physical wudu from hadath and internal cleansing of the heart from pride, malice, and riya.',
      },
    ],
  },

