  // =========================================================================
  // 18. AL-MUWATTA (امام دار الہجرۃ مالک بن انس)
  // =========================================================================
  'CANON-FIQ-MAL-002': {
    workId: 'CANON-FIQ-MAL-002',
    verifiedExternalUrl: 'https://sunnah.com/malik',
    verifiedExternalName: 'Sunnah.com (Al-Muwatta of Imam Malik)',
    chapters: [
      {
        chapterId: 'muw_1',
        chapterTitleArabic: 'كِتَابُ وُقُوتِ الصَّلَاةِ: فِي وَقْتِ صَلَاةِ الصُّبْحِ وَالظُّهْرِ',
        chapterTitleUrdu: 'پہلا باب: اوقاتِ نماز اور عملِ اہل مدینہ کا بیان',
        chapterTitleEnglish: 'Chapter 1: The Prescribed Timings of Prayer in Madinah',
        arabicMatn: `عَنْ مَالِكٍ، عَنْ نَافِعٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ:
«الَّذِي تَفُوتُهُ صَلَاةُ الْعَصْرِ كَأَنَّمَا وُتِرَ أَهْلَهُ وَمَالَهُ».

وَقَالَ مَالِكٌ: وَقْتُ الظُّهْرِ إِذَا زَالَتِ الشَّمْسُ، وَوَقْتُ الْعَصْرِ إِذَا كَانَ ظِلُّ كُلِّ شَيْءٍ مِثْلَهُ، وَأَحَبُّ الأَعْمَالِ إِلَى اللَّهِ الصَّلَاةُ لِوَقْتِهَا.`,
        urduTranslation: `سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: "جس شخص کی عصر کی نماز چھوٹ گئی تو گویا اس کے گھر والے اور اس کا مال و دولت سب لٹ گیا!"۔

اور امام مالک رحمۃ اللہ علیہ فرماتے ہیں: ظہر کا وقت اس وقت شروع ہوتا ہے جب سورج ڈھل جائے، اور جمہور کے نزدیک عصر کا وقت اس وقت شروع ہوتا ہے جب ہر چیز کا سایہ اس کے مثل ہو جائے، اور اللہ کو سب سے محبوب عمل وقت پر نماز ادا کرنا ہے۔`,
        englishSynopsis: 'Imam Malik transmits the gravest warning against missing the Asr prayer and records the living consensus practice of Madinah.',
        scholarlyNotes: 'The foundational masterwork of the Maliki school, praised by Imam al-Shafi\'i as the most authentic book on earth after the Quran in its era.',
      },
    ],
  },

  // =========================================================================
  // 19. DALA'IL AL-KHAYRAT (امام محمد بن سلیمان الجزولی)
  // =========================================================================
  'CANON-DUA-005': {
    workId: 'CANON-DUA-005',
    verifiedExternalUrl: 'https://archive.org/search?query=dalail+khayrat+al+jazuli',
    verifiedExternalName: 'Classical Liturgies Archives (Dala\'il al-Khayrat)',
    chapters: [
      {
        chapterId: 'dal_1',
        chapterTitleArabic: 'أَسْمَاءُ سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ ﷺ وَفَضْلُ الصَّلَاةِ عَلَيْهِ',
        chapterTitleUrdu: 'پہلا باب: رسول اللہ ﷺ کے اسمائے مبارکہ اور درود شریف کے فضائل',
        chapterTitleEnglish: 'Chapter 1: The Blessed Names of the Prophet ﷺ and Virtues of Salawat',
        arabicMatn: `«اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ سَيِّدِ الأَوَّلِينَ وَالآخِرِينَ، اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي كُلِّ وَقْتٍ وَحِينٍ. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ حَتَّى تَرِثَ الأَرْضَ وَمَنْ عَلَيْهَا وَأَنْتَ خَيْرُ الْوَارِثِينَ».

مُحَمَّدٌ ﷺ، أَحْمَدُ ﷺ، حَامِدٌ ﷺ، مَحْمُودٌ ﷺ، قَاسِمٌ ﷺ، شَافِعٌ ﷺ، نَبِيُّ الرَّحْمَةِ ﷺ، صَاحِبُ التَّاجِ وَالْمِعْرَاجِ وَالْبُرَاقِ وَالْعَلَمِ.`,
        urduTranslation: `اے اللہ! ہمارے آقا و مولا حضرت محمد ﷺ پر رحمت نازل فرما جو اگلوں اور پچھلوں کے سردار ہیں۔ اے اللہ! ہمارے آقا حضرت محمد ﷺ پر ہر وقت اور ہر لمحہ رحمت نازل فرما۔ اے اللہ! ہمارے آقا حضرت محمد ﷺ پر رحمت نازل فرما یہاں تک کہ تو زمین اور اس کے رہنے والوں کا وارث ہو جائے اور تو سب سے بہتر وارث ہے۔

وہ محمد ہیں ﷺ، وہ احمد ہیں ﷺ، وہ حامد ہیں ﷺ، وہ محمود ہیں ﷺ، وہ قاسم (بانٹنے والے) ہیں ﷺ، وہ شفاعت فرمانے والے ہیں ﷺ، وہ نبیِ رحمت ہیں ﷺ، تاج، معراج، براق اور پرچم والے ہیں ﷺ!`,
        englishSynopsis: 'Imam al-Jazuli’s opening litany commemorating the blessed names and infinite stations of the Prophet Muhammad ﷺ.',
        scholarlyNotes: 'The premier text of devotion recited across North Africa, Turkey, the Levant, and the Indian subcontinent for centuries.',
      },
    ],
  },

