        arabicMatn: `قَالَ الإِمَامُ الأَعْظَمُ أَبُو حَنِيفَةَ رَضِيَ اللَّهُ عَنْهُ:
«أَصْلُ التَّوْحِيدِ وَمَا يَصِحُّ الاعْتِقَادُ عَلَيْهِ: أَنْ يَقُولَ: آمَنْتُ بِاللَّهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْبَعْثِ بَعْدَ الْمَوْتِ، وَالْقَدَرِ خَيْرِهِ وَشَرِّهِ مِنَ اللَّهِ تَعَالَى، وَالْحِسَابِ، وَالْمِيزَانِ، وَالْجَنَّةِ، وَالنَّارِ، وَحَقٌّ كُلُّهَا. وَاللَّهُ تَعَالَى وَاحِدٌ لَا مِنْ طَرِيقِ الْعَدَدِ وَلَكِنْ مِنْ طَرِيقِ أَنَّهُ لَا شَرِيكَ لَهُ، لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ. وَالْقُرْآنُ كَلَامُ اللَّهِ تَعَالَى غَيْرُ مَخْلُوقٍ».`,
        urduTranslation: `امام اعظم ابو حنیفہ نعمان بن ثابت رضی اللہ عنہ فرماتے ہیں:
"اصل توحید اور جس پر اعتقاد درست ہوتا ہے وہ یہ ہے کہ بندہ اقرار کرے: میں ایمان لایا اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر، اس کے رسولوں پر، موت کے بعد دوبارہ زندہ کیے جانے پر، اور اچھی اور بری تقدیر کے اللہ تعالیٰ کی طرف سے ہونے پر، اور حساب، میزان، جنت اور دوزخ سب برحق ہیں۔ اور اللہ تعالیٰ ایک ہے عدد کے اعتبار سے نہیں بلکہ اس اعتبار سے کہ اس کا کوئی شریک نہیں، نہ اس کی کوئی اولاد ہے نہ وہ کسی کی اولاد ہے اور نہ کوئی اس کا ہمسر ہے۔ اور قرآن مجید اللہ تعالیٰ کا کلام ہے جو غیر مخلوق ہے"۔`,
