  // 48. FUTUH AL-GHAYB (فتوح الغيب) — SHAYKH ABD AL-QADIR AL-JILANI
  // =========================================================================
  'CANON-TAZ-005': {
    workId: 'CANON-TAZ-005',
    verifiedExternalUrl: 'https://archive.org/search?query=futuh+al+ghayb+jilani',
    verifiedExternalName: 'Classical Spiritual Archives (Futuh al-Ghayb - Shaykh Abdul Qadir Jilani)',
    chapters: [
      {
        chapterId: 'fut_1',
        chapterTitleArabic: 'الْمَقَالَةُ الأُولَى: فِيمَا لا بُدَّ لِكُلِّ مُؤْمِنٍ فِي سَائِرِ أَحْوَالِهِ',
        chapterTitleUrdu: 'پہلا مقالہ: ہر مومن کے لیے تین ناگزیر روحانی ارکان کا بیان',
        chapterTitleEnglish: 'Discourse 1: The Three Inviolable Duties of the Seeker in Every State',
        arabicMatn: `قَالَ سَيِّدُنَا وَمَوْلانَا الشَّيْخُ عَبْدُ الْقَادِرِ الْجِيلانِيُّ رَضِيَ اللَّهُ عَنْهُ:
«لا بُدَّ لِكُلِّ مُؤْمِنٍ فِي سَائِرِ أَحْوَالِهِ مِنْ ثَلاثَةِ أَشْيَاءَ:
١. أَمْرٌ يَمْتَثِلُهُ.
٢. وَنَهْيٌ يَجْتَنِبُهُ.
٣. وَقَدَرٌ يَرْضَى بِهِ.

فَأَقَلُّ حَالَةِ الْمُؤْمِنِ لا تَخْلُو مِنْ أَحَدِ هَذِهِ الثَّلاثَةِ، فَيَنْبَغِي لَهُ أَنْ يُلْزِمَ هَمَّهُ بِهَا، وَيُحَدِّثَ بِهَا نَفْسَهُ، وَيُؤَاخِذَ بِهَا جَوَارِحَهُ فِي سَائِرِ الأَحْوَالِ.

فَإِذَا أَمَرَهُ اللَّهُ عَزَّ وَجَلَّ بِأَمْرٍ فَعَلَيْهِ بِالْمُبَادَرَةِ وَالطَّاعَةِ دُونَ تَوَانٍ، وَإِذَا نَهَاهُ عَنْ نَهْيٍ فَعَلَيْهِ بِالْكُفِّ وَالْفِرَارِ دُونَ مُدَاهَنَةٍ، وَإِذَا جَرَى عَلَيْهِ قَدَرٌ فَعَلَيْهِ بِالصَّبْرِ وَالرِّضَا وَالتَّسْلِيمِ دُونَ شَكْوَى، فَبِذَلِكَ يَسْلَمُ دِينُهُ وَيَسْتَقِيمُ يَقِينُهُ».`,
        urduTranslation: `سیدنا غوث الاعظم شیخ عبد القادر جیلانی رضی اللہ عنہ فرماتے ہیں:
"ہر مومن کے لیے اس کی زندگی کے تمام احوال میں تین باتوں کی پابندی ناگزیر ہے:
۱. ایک حکمِ الٰہی جس کی وہ اطاعت کرے۔
۲. ایک ممانعت جس سے وہ مکمل اجتناب کرے۔
۳. اور ایک تقدیرِ الٰہی کا فیصلہ جس پر وہ دل و جان سے راضی رہے۔

پس مومن کا ادنیٰ ترین حال بھی ان تینوں سے خالی نہیں ہوتا۔ اس پر لازم ہے کہ وہ اپنے دل و دماغ کو انہی کے ساتھ وابستہ رکھے، اپنے نفس کو انہی کی نصیحت کرتا رہے، اور اپنے تمام اعضاء کو ہر گھڑی انہی کا پابند بنائے۔

جب اللہ تعالیٰ اسے کوئی حکم فرمائے تو سستی کے بغیر فوری تعمیل کرے؛ جب کسی گناہ سے روکے تو لیت و لعل کے بغیر اس سے بھاگے؛ اور جب اس پر تقدیر کا کوئی فیصلہ جاری ہو تو شکوہ و شکایت کے بغیر صبر، رضا اور خود سپردگی کا مظاہرہ کرے۔ اسی راستے پر چلنے سے اس کا دین سلامت رہتا ہے اور اس کا یقین کامل ہوتا ہے"۔`,
        englishSynopsis: 'Foundational spiritual counsel mapping the totality of Muslim practice: absolute obedience to divine commands, flight from sin, and contented surrender to divine destiny.',
        scholarlyNotes: 'Authentically transmitted across classical spiritual lineages from the discourses of Shaykh Abd al-Qadir al-Jilani in Baghdad.',
      },
    ],
  },

